UPDATE crm_sequences 
SET trigger_event = 'ai_condition',
    definition = '{"nodes": [{"id": "start", "type": "custom", "position": {"x": 400, "y": 0}, "data": {"label": "Start", "conditionSql": "SELECT p.id, ''user'' AS recipient_type, p.email, p.phone_number AS phone, p.full_name AS name, p.state_code, p.city, p.zip_code, p.home_community_h3_index AS community_h3, p.created_at AS joined_at, (p.email IS NOT NULL) AS accepts_email, COALESCE(p.sms_enabled, false) AS accepts_sms FROM profiles p WHERE NOT EXISTS (SELECT 1 FROM market_products mp WHERE mp.seller_id = p.id) AND p.created_at < now() - interval ''7 days'' AND p.email NOT LIKE ''%@test.local'' AND p.email NOT LIKE ''%@casagrown.local'' AND p.email NOT ILIKE ''casabot@casagrown.com'' AND p.email NOT ILIKE ''%@example.com'' AND p.email NOT ILIKE ''%@test.com''", "type": "input"}}, {"id": "n2", "type": "custom", "position": {"x": 400, "y": 180}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n3", "type": "custom", "position": {"x": 400, "y": 360}, "data": {"label": "Email Intro", "userLabel": "Email Intro", "html": "<div style=\"background-color: #f9f9f9; padding: 30px 15px; font-family: ''Helvetica Neue'', Helvetica, Arial, sans-serif; color: #333333; line-height: 1.6;\">\n  <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"max-width: 600px; background-color: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 10px rgba(0,0,0,0.05); border: 1px solid #e0e0e0;\">\n    \n    <!-- Header Section with Logo and Tagline -->\n    <tr>\n      <td style=\"padding: 30px 30px 20px 30px; text-align: center; border-bottom: 3px solid #4CAF50;\">\n        <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n          <tr>\n            <td style=\"vertical-align: middle;\">\n              <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" width=\"50\" style=\"width: 50px; height: auto; display: block; margin-right: 12px;\" />\n            </td>\n            <td style=\"vertical-align: middle; text-align: left;\">\n              <span style=\"font-size: 28px; font-weight: bold; color: #2E7D32; font-family: ''Helvetica Neue'', Helvetica, Arial, sans-serif; display: block; line-height: 1;\">CasaGrown</span>\n              <span style=\"font-size: 12px; text-transform: uppercase; letter-spacing: 2px; color: #81C784; font-weight: bold; display: block; margin-top: 4px;\">fresh &bull; local &bull; trusted</span>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n\n    <!-- Body Content -->\n    <tr>\n      <td style=\"padding: 40px 30px 30px 30px;\">\n        <h1 style=\"font-size: 22px; color: #2E7D32; margin-top: 0; margin-bottom: 20px; font-weight: 700; text-align: center;\">Turn Your Backyard Harvest Into Local Earnings! \ud83c\udf3f</h1>\n        \n        <p style=\"font-size: 16px; margin-bottom: 18px;\">Hi there,</p>\n\n        <p style=\"font-size: 16px; margin-bottom: 18px;\">Have you ever looked at your backyard garden and wondered, <strong>\"How much could I actually earn by selling this fresh, home-grown produce to my neighbors?\"</strong></p>\n        \n        <p style=\"font-size: 16px; margin-bottom: 18px;\">You are receiving this email because you expressed interest in turning your backyard surplus into local earnings. Whether you have a bounty of tomatoes, fresh herbs, or citrus, your neighborhood is hungry for what you are growing!</p>\n        \n        <!-- Video Promo / Highlight Section -->\n        <div style=\"text-align: center; margin: 25px 0;\">\n          <p style=\"font-size: 16px; margin-bottom: 12px; font-weight: bold; color: #2E7D32;\">Ready to see how simple it is?</p>\n          <p style=\"font-size: 15px; margin-bottom: 15px; color: #555555;\">Watch this quick, fun 2-minute video to see exactly how CasaGrown works:</p>\n          <a href=\"https://casagrown.com/r/1s5d5i5s\" style=\"display: inline-block; text-decoration: none; border: none; outline: none; margin-bottom: 15px; max-width: 320px; width: 100%;\">\n            <img src=\"https://fzdmszvfeewpwswlnfyk.supabase.co/storage/v1/object/public/marketing-assets/crm/1781751989084-full_workflow_with_overlay.jpg\" alt=\"Watch how CasaGrown works\" style=\"max-width: 100%; height: auto; border-radius: 6px; box-shadow: 0 4px 8px rgba(0,0,0,0.1); display: block; margin: 0 auto;\" />\n          </a>\n          <br />\n          <a href=\"https://casagrown.com/r/1s5d5i5s\" style=\"color: #2E7D32; text-decoration: underline; font-size: 16px; font-weight: bold;\">Click here to watch the 2-minute video &gt;</a>\n        </div>\n\n        <!-- Urgent / Action-oriented Highlight Box -->\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: #E8F5E9; border-left: 4px solid #4CAF50; border-radius: 4px; margin: 25px 0;\">\n          <tr>\n            <td style=\"padding: 20px;\">\n              <h3 style=\"margin-top: 0; margin-bottom: 8px; color: #2E7D32; font-size: 18px; font-weight: bold;\">Set Up is Incredibly Fast!</h3>\n              <p style=\"margin: 0; font-size: 15px; color: #388E3C; font-weight: 500;\">We highly recommend getting the app on your phone today. In our next email, we will send you a direct link to help you create your very first listing, but having the app installed beforehand makes the process seamless!</p>\n            </td>\n          </tr>\n        </table>\n\n        <!-- Call to Action Button -->\n        <div style=\"text-align: center; margin: 30px 0;\">\n          <a href=\"https://casagrown.com\" style=\"background-color: #4CAF50; color: #ffffff; text-decoration: none; padding: 15px 35px; font-size: 18px; font-weight: bold; border-radius: 5px; display: inline-block; box-shadow: 0 3px 6px rgba(76, 175, 80, 0.3);\">Visit CasaGrown.com to Download the App</a>\n        </div>\n\n        <p style=\"font-size: 16px; margin-top: 30px; margin-bottom: 0; border-top: 1px solid #eeeeee; padding-top: 20px;\">\n          Warmly,<br />\n          <strong>The CasaGrown Team</strong>\n        </p>\n      </td>\n    </tr>\n\n    <!-- Footer Section -->\n    <tr>\n      <td style=\"background-color: #f1f1f1; padding: 20px 30px; text-align: center; font-size: 13px; color: #666666; border-bottom-left-radius: 8px; border-bottom-right-radius: 8px;\">\n        <p style=\"margin: 0; font-weight: 500;\">Have questions or need a hand? We''re here for you!</p>\n        <p style=\"margin: 5px 0 0 0;\">Reach out to us anytime at <a href=\"mailto:support@casagrown.com\" style=\"color: #2E7D32; text-decoration: underline; font-weight: bold;\">support@casagrown.com</a></p>\n      </td>\n    </tr>\n  </table>\n</div>", "text": "CasaGrown\nfresh \u2022 local \u2022 trusted\n\nTurn Your Backyard Harvest Into Local Earnings! \ud83c\udf3f\n\nHi there,\n\nHave you ever looked at your backyard garden and wondered, \"How much could I actually earn by selling this fresh, home-grown produce to my neighbors?\"\n\nYou are receiving this email because you expressed interest in turning your backyard surplus into local earnings. Whether you have a bounty of tomatoes, fresh herbs, or citrus, your neighborhood is hungry for what you are growing!\n\nReady to see how simple it is?\n\nWatch this quick, fun 2-minute video to see exactly how CasaGrown works:\n\nClick here to watch the 2-minute video (https://casagrown.com/r/1s5d5i5s)\n\nSet Up is Incredibly Fast!\n\nWe highly recommend getting the app on your phone today. In our next email, we will send you a direct link to help you create your very first listing, but having the app installed beforehand makes the process seamless!\n\nVisit CasaGrown.com to Download the App (https://casagrown.com)\n\nWarmly,\nThe CasaGrown Team", "subject": "Welcome to CasaGrown!", "type": "action_email"}}, {"id": "n4", "type": "custom", "position": {"x": 400, "y": 540}, "data": {"delayDays": 0, "delayHours": 5, "delayMinutes": 0, "type": "wait"}}, {"id": "n5", "type": "custom", "position": {"x": 400, "y": 666.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n6", "type": "custom", "position": {"x": 400, "y": 792.0}, "data": {"label": "Day 1", "userLabel": "Day 1", "html": "<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"background-color: #f9f9f9; font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 0; width: 100%;\">\n  <tr>\n    <td align=\"center\" style=\"padding: 20px 0;\">\n      <table width=\"100%\" max-width=\"600\" style=\"background-color: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; max-width: 600px; width: 100%;\" cellpadding=\"0\" cellspacing=\"0\">\n        <!-- Header -->\n        <tr>\n          <td style=\"padding: 40px 40px 20px 40px; text-align: center;\">\n            <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown\" style=\"border: 0; height: auto; max-width: 180px; width: 100%; display: block; margin: 0 auto 10px auto;\" />\n            <span style=\"color: #0f172a; font-size: 24px; font-weight: bold; display: block; margin-bottom: 4px; letter-spacing: -0.5px;\">CasaGrown</span>\n            <p style=\"color: #64748b; font-size: 14px; font-style: italic; margin: 0; letter-spacing: 1px;\">fresh &bull; trusted &bull; local</p>\n          </td>\n        </tr>\n\n        <!-- Content Body -->\n        <tr>\n          <td style=\"color: #334155; font-size: 16px; line-height: 1.6; padding: 20px 40px;\">\n            <p style=\"margin-top: 0;\">Hey there,</p>\n            \n            <p>You''re here because something''s growing &mdash; more lemons, tomatoes, herbs, eggs, or flowers than your household can use. CasaGrown turns that surplus into income, and your neighborhood into your customers.</p>\n            \n            <p>Here''s the whole thing in three steps:</p>\n\n            <!-- Step 1 -->\n            <div style=\"margin-bottom: 20px; padding-left: 10px; border-left: 4px solid #10b981;\">\n              <strong style=\"color: #0f172a; font-size: 18px; display: block; margin-bottom: 4px;\">1. List it in two minutes</strong>\n              <span style=\"color: #334155;\">Snap a photo, set a price, pick pickup or delivery. The wizard does the rest.</span>\n            </div>\n\n            <!-- Step 2 -->\n            <div style=\"margin-bottom: 20px; padding-left: 10px; border-left: 4px solid #10b981;\">\n              <strong style=\"color: #0f172a; font-size: 18px; display: block; margin-bottom: 4px;\">2. Your listing works while you don''t</strong>\n              <span style=\"color: #334155;\">It stays live and active for the duration of your specified pickup or delivery windows for the week. No weekend market to catch, no rigid deadlines.</span>\n            </div>\n\n            <!-- Step 3 -->\n            <div style=\"margin-bottom: 25px; padding-left: 10px; border-left: 4px solid #10b981;\">\n              <strong style=\"color: #0f172a; font-size: 18px; display: block; margin-bottom: 4px;\">3. Share it to your neighborhood</strong>\n              <span style=\"color: #334155;\">Drop your unique listing link in your WhatsApp, Nextdoor, or Facebook group. That''s how the right buyers nearby find it. We make it incredibly easy&mdash;with just a couple of taps, you can share a beautifully formatted copy directly to your groups.</span>\n            </div>\n\n            <p>That third step is the one that turns a listing into a sale. The neighbors who want what you grow are already in those groups &mdash; they just don''t know it''s a few doors away yet.</p>\n\n            <!-- Quote/Estimate Box -->\n            <table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"background-color: #f0fdf4; border-radius: 8px; margin: 30px 0;\">\n              <tr>\n                <td style=\"padding: 20px; text-align: center; color: #166534; font-size: 16px; font-style: italic; line-height: 1.5;\">\n                  \"We estimate the average CasaGrown grower can earn up to $820 a year from produce that might otherwise go to waste. It all starts with one listing.\"\n                </td>\n              </tr>\n            </table>\n\n            <p>Your first step is simple. List one thing you''re already growing.</p>\n\n            <p style=\"margin-bottom: 0;\">Glad you''re here,<br /><strong>Rahul</strong><br /><span style=\"color: #64748b; font-size: 14px;\">Founder, CasaGrown</span></p>\n          </td>\n        </tr>\n\n        <!-- Call to Action Section -->\n        <tr>\n          <td style=\"background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 40px; text-align: center; border-bottom-left-radius: 8px; border-bottom-right-radius: 8px;\">\n            <h3 style=\"color: #0f172a; font-size: 20px; margin: 0 0 10px 0;\">Your First Step</h3>\n            <p style=\"color: #475569; font-size: 16px; margin: 0 0 8px 0; font-weight: bold;\">Create your first listing</p>\n            <p style=\"color: #64748b; font-size: 14px; margin: 0 0 24px 0;\">Photo, price, pickup window. Two minutes &mdash; then share it.</p>\n            \n            <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"margin: 0 auto;\">\n              <tr>\n                <td align=\"center\" style=\"border-radius: 6px; background-color: #10b981;\">\n                  <a href=\"https://casagrown.com/r/3v25u7dz\" target=\"_blank\" style=\"font-size: 16px; font-family: Helvetica, Arial, sans-serif; color: #ffffff; text-decoration: none; border-radius: 6px; padding: 14px 30px; border: 1px solid #10b981; display: inline-block; font-weight: bold;\">\n                    Create My First Listing &rarr;\n                  </a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n  <!-- Footer Support Info -->\n  <tr>\n    <td align=\"center\" style=\"padding: 20px 0 40px 0;\">\n      <table width=\"100%\" max-width=\"600\" style=\"max-width: 600px; width: 100%;\" cellpadding=\"0\" cellspacing=\"0\">\n        <tr>\n          <td style=\"color: #94a3b8; font-size: 12px; line-height: 1.5; text-align: center; padding: 0 20px;\">\n            This is an automated message, please do not reply directly to this email. Need a hand or have questions? We''re here to help! Reach out to us anytime at \n            <a href=\"mailto:support@casagrown.com\" style=\"color: #10b981; text-decoration: underline;\">support@casagrown.com</a>.\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>", "text": "CasaGrown\nfresh \u2022 trusted \u2022 local\n\nHey there,\n\nYou''re here because something''s growing \u2014 more lemons, tomatoes, herbs, eggs, or flowers than your household can use. CasaGrown turns that surplus into income, and your neighborhood into your customers.\n\nHere''s the whole thing in three steps:\n\n1. List it in two minutes\nSnap a photo, set a price, pick pickup or delivery. The wizard does the rest.\n\n2. Your listing works while you don''t\nIt stays live and active for the duration of your specified pickup or delivery windows for the week. No weekend market to catch, no rigid deadlines.\n\n3. Share it to your neighborhood\nDrop your unique listing link in your WhatsApp, Nextdoor, or Facebook group. That''s how the right buyers nearby find it. We make it incredibly easy\u2014with just a couple of taps, you can share a beautifully formatted copy directly to your groups.\n\nThat third step is the one that turns a listing into a sale. The neighbors who want what you grow are already in those groups \u2014 they just don''t know it''s a few doors away yet.\n\n\"We estimate the average CasaGrown grower can earn up to $820 a year from produce that might otherwise go to waste. It all starts with one listing.\"\n\nYour first step is simple. List one thing you''re already growing.\n\nGlad you''re here,\nRahul\nFounder, CasaGrown\n\n\nYour First Step\n\nCreate your first listing\nPhoto, price, pickup window. Two minutes \u2014 then share it.\n\nCreate My First Listing (https://casagrown.com/r/7339wp2m)", "subject": "Welcome to CasaGrown. Your backyard is about to pay you back.", "type": "action_email"}}, {"id": "n7", "type": "custom", "position": {"x": 400, "y": 972.0}, "data": {"delayDays": 0, "delayHours": 36, "delayMinutes": 0, "type": "wait"}}, {"id": "n8", "type": "custom", "position": {"x": 400, "y": 1098.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n9", "type": "custom", "position": {"x": 400, "y": 1224.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n10", "type": "custom", "position": {"x": 50, "y": 1350.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n11", "type": "custom", "position": {"x": 400, "y": 1350.0}, "data": {"label": "Day 3", "userLabel": "Day 3", "html": "<div style=\"font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333333; line-height: 1.6;\">\n  \n  <!-- Header / Branding Section -->\n  <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"margin-bottom: 30px; border-bottom: 1px solid #eeeeee; padding-bottom: 20px;\">\n    <tr>\n      <td width=\"60\" valign=\"middle\">\n        <a href=\"https://casagrown.com\" style=\"text-decoration: none; color: #2e7d32;\">\n          <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" width=\"50\" height=\"50\" style=\"display: block; border: 0;\" />\n        </a>\n      </td>\n      <td valign=\"middle\" style=\"padding-left: 10px;\">\n        <span style=\"font-size: 24px; font-weight: bold; color: #2e7d32; display: block; line-height: 1.2;\">CasaGrown.com</span>\n        <span style=\"font-size: 12px; color: #757575; letter-spacing: 1.5px; text-transform: uppercase; display: block; margin-top: 2px;\">fresh &bull; trusted &bull; local</span>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Email Body Content -->\n  <p style=\"font-size: 16px; margin-bottom: 20px;\">Hey there,</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 20px; font-weight: bold; color: #2e7d32;\">The number-one thing that stops people is thinking listing is work. It isn''t.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 20px;\">Snap a photo. CasaGrown auto-fills the category. You set the price and whether you want pickup, delivery, or both. Done \u2014 and it stays live for the whole week, not just a weekend.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 25px;\">Then the part that matters: at the end, CasaGrown hands you a link to share. Drop it in your building''s WhatsApp, your Nextdoor, your street''s Facebook group. That''s the difference between a listing nobody sees and a bag of lemons gone by midweek.</p>\n\n  <!-- Testimonial Block -->\n  <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: #f9f9f9; border-left: 4px solid #2e7d32; margin-bottom: 25px;\">\n    <tr>\n      <td style=\"padding: 15px 20px;\">\n        <p style=\"font-style: italic; font-size: 15px; margin: 0; color: #555555;\">\n          \"I listed in the time it took my coffee to cool, then shared it to my building''s WhatsApp. Sold out by that evening.\"\n        </p>\n        <p style=\"font-size: 13px; font-weight: bold; margin: 5px 0 0 0; color: #2e7d32;\">\n          \u2014 Maria, Menlo Park\n        </p>\n      </td>\n    </tr>\n  </table>\n\n  <p style=\"font-size: 16px; margin-bottom: 20px; font-weight: bold;\">Two minutes to list. One tap to share. That''s the whole job.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 30px;\">\n    You''ve got this,<br />\n    <strong>Rahul</strong><br />\n    Founder, CasaGrown\n  </p>\n\n  <!-- Call to Action Section -->\n  <div style=\"background-color: #f1f8e9; border-radius: 8px; padding: 25px; text-align: center; margin-top: 30px; border: 1px solid #dcedc8;\">\n    <h3 style=\"margin-top: 0; color: #2e7d32; font-size: 20px; margin-bottom: 10px;\">Start Now</h3>\n    <p style=\"font-size: 15px; margin-bottom: 20px; color: #555555;\">Post your first listing. The wizard walks you through it \u2014 then shows you how to share.</p>\n    \n    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin: 0 auto;\">\n      <tr>\n        <td align=\"center\" bgcolor=\"#2e7d32\" style=\"border-radius: 4px;\">\n          <a href=\"https://casagrown.com/r/3v25u7dz\" target=\"_blank\" style=\"font-size: 16px; font-weight: bold; color: #ffffff; text-decoration: none; padding: 12px 30px; display: inline-block;\">\n            List Something Now &rarr;\n          </a>\n        </td>\n      </tr>\n    </table>\n  </div>\n\n  <!-- Support Footer Section -->\n  <div style=\"margin-top: 30px; border-top: 1px solid #eeeeee; padding-top: 20px; text-align: center;\">\n    <p style=\"font-size: 14px; color: #757575; margin: 0;\">\n      Need any assistance? We are here to help! Reach out to us anytime at \n      <a href=\"mailto:support@casagrown.com\" style=\"color: #2e7d32; text-decoration: underline;\">support@casagrown.com</a>.\n    </p>\n  </div>\n\n</div>", "text": "CasaGrown.com\nfresh \u2022 trusted \u2022 local\n\nHey there,\n\nThe number-one thing that stops people is thinking listing is work. It isn''t.\n\nSnap a photo. CasaGrown auto-fills the category. You set the price and whether you want pickup, delivery, or both. Done \u2014 and it stays live for the whole week, not just a weekend.\n\nThen the part that matters: at the end, CasaGrown hands you a link to share. Drop it in your building''s WhatsApp, your Nextdoor, your street''s Facebook group. That''s the difference between a listing nobody sees and a bag of lemons gone by midweek.\n\n\"I listed in the time it took my coffee to cool, then shared it to my building''s WhatsApp. Sold out by that evening.\"\n\u2014 Maria, Menlo Park\n\nTwo minutes to list. One tap to share. That''s the whole job.\n\nYou''ve got this,\nRahul\nFounder, CasaGrown\n\nStart Now\n\nPost your first listing. The wizard walks you through it \u2014 then shows you how to share.\n\nList Something Now: https://casagrown.com/r/7339wp2m\n\nNeed any assistance? We are here to help! Reach out to us anytime at support@casagrown.com.", "subject": "Listing takes two minutes. Sharing it takes thirty seconds.", "type": "action_email"}}, {"id": "n12", "type": "custom", "position": {"x": 400, "y": 1530.0}, "data": {"delayDays": 0, "delayHours": 64, "delayMinutes": 0, "type": "wait"}}, {"id": "n13", "type": "custom", "position": {"x": 400, "y": 1656.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n14", "type": "custom", "position": {"x": 400, "y": 1782.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n15", "type": "custom", "position": {"x": 50, "y": 1908.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n16", "type": "custom", "position": {"x": 400, "y": 1908.0}, "data": {"label": "Day 6", "userLabel": "Day 6", "html": "<div style=\"font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333333; line-height: 1.6; background-color: #ffffff;\">\n\n  <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"width: 100%; margin-bottom: 30px;\">\n    <tr>\n      <td style=\"width: 60px; vertical-align: middle;\">\n        <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" style=\"width: 50px; height: auto; display: block; max-width: 100%;\" />\n      </td>\n      <td style=\"vertical-align: middle; padding-left: 10px;\">\n        <div style=\"font-size: 24px; font-weight: bold; color: #2e7d32; line-height: 1.2;\">CasaGrown</div>\n        <div style=\"font-size: 14px; color: #666666; font-style: italic; margin-top: 2px;\">fresh &bull; trusted &bull; local</div>\n      </td>\n    </tr>\n  </table>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">Hey there,</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">It''s the most common worry we hear, and it''s fair. Here''s the honest answer: <strong>listings don''t sell when nobody knows they exist.</strong></p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">CasaGrown puts your produce in front of neighbors who are looking \u2014 but the fastest sales happen when you share your listing to the groups you''re already in. Your WhatsApp neighborhood chat. Nextdoor. The Facebook group for your street. The people there have been wanting exactly what you grow; they just didn''t know it was 0.4 miles away.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">And because your listing stays live all week, you''re not racing a deadline. Share it once, share it again midweek, and let it work.</p>\n\n  <div style=\"background-color: #f9f9f9; border-left: 4px solid #4CAF50; padding: 15px; margin: 25px 0; border-radius: 4px;\">\n    <p style=\"font-style: italic; font-size: 15px; margin: 0; color: #555555;\">\n      \"I was sure nobody would buy my tomatoes. I shared the listing to our street''s WhatsApp. Three neighbors messaged me within an hour.\"\n    </p>\n    <p style=\"font-size: 14px; font-weight: bold; margin: 5px 0 0 0; color: #333333;\">\u2014 Maria</p>\n  </div>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">The produce is real. The buyers are nearby. Sharing is what connects them.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 30px;\">\n    Give it a shot,<br />\n    <strong>Rahul</strong><br />\n    Founder, CasaGrown\n  </p>\n\n  <div style=\"background-color: #eef7ee; border: 1px solid #cce8cc; border-radius: 8px; padding: 25px; text-align: center; margin-top: 30px; margin-bottom: 20px;\">\n    <h3 style=\"color: #2e7d32; font-size: 20px; margin-top: 0; margin-bottom: 10px;\">List It, Then Share It</h3>\n    <p style=\"font-size: 15px; margin-bottom: 20px; color: #444444;\">\n      Put one thing up this week. Already listed? Open it and share the link again \u2014 midweek shares sell.\n    </p>\n    <div style=\"margin-top: 20px;\">\n      <a href=\"https://casagrown.com/r/3v25u7dz\" style=\"background-color: #4CAF50; color: #ffffff; text-decoration: none; padding: 14px 28px; font-size: 16px; font-weight: bold; border-radius: 5px; display: inline-block; transition: background-color 0.2s ease;\">\n        Create a Listing &rarr;\n      </a>\n    </div>\n  </div>\n\n</div>", "text": "CasaGrown\nfresh \u2022 trusted \u2022 local\n\nHey there,\n\nIt''s the most common worry we hear, and it''s fair. Here''s the honest answer: listings don''t sell when nobody knows they exist.\n\nCasaGrown puts your produce in front of neighbors who are looking \u2014 but the fastest sales happen when you share your listing to the groups you''re already in. Your WhatsApp neighborhood chat. Nextdoor. The Facebook group for your street. The people there have been wanting exactly what you grow; they just didn''t know it was 0.4 miles away.\n\nAnd because your listing stays live all week, you''re not racing a deadline. Share it once, share it again midweek, and let it work.\n\n\"I was sure nobody would buy my tomatoes. I shared the listing to our street''s WhatsApp. Three neighbors messaged me within an hour.\"\n\u2014 Maria\n\nThe produce is real. The buyers are nearby. Sharing is what connects them.\n\nGive it a shot,\nRahul\nFounder, CasaGrown\n\n\nList It, Then Share It\n\nPut one thing up this week. Already listed? Open it and share the link again \u2014 midweek shares sell.\n\nCreate a Listing: https://casagrown.com/r/7339wp2m", "subject": "\u201cWhat if I list it and nobody buys?\u201d", "type": "action_email"}}, {"id": "n17", "type": "custom", "position": {"x": 400, "y": 2088.0}, "data": {"delayDays": 0, "delayHours": 84, "delayMinutes": 0, "type": "wait"}}, {"id": "n18", "type": "custom", "position": {"x": 400, "y": 2214.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n19", "type": "custom", "position": {"x": 400, "y": 2340.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n20", "type": "custom", "position": {"x": 50, "y": 2466.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n21", "type": "custom", "position": {"x": 400, "y": 2466.0}, "data": {"label": "Day 10", "userLabel": "Day 10", "html": "<div style=\"font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333333; line-height: 1.6; background-color: #ffffff;\">\n  \n  <!-- Logo Header Section -->\n  <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom: 30px;\">\n    <tr>\n      <td align=\"center\" style=\"padding: 10px 0;\">\n        <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown\" style=\"width: 80px; height: auto; display: block; margin-bottom: 10px;\" />\n        <div style=\"font-size: 28px; font-weight: bold; color: #2e7d32; letter-spacing: -0.5px; line-height: 1.2;\">CasaGrown</div>\n        <div style=\"font-size: 12px; text-transform: uppercase; letter-spacing: 2px; color: #666666; margin-top: 4px; font-weight: 600;\">fresh * local * trusted</div>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Main Body Content -->\n  <p style=\"font-size: 16px; margin-bottom: 20px;\">Hey there,</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 20px;\">If you''ve listed something \u2014 nice work. But remember: <strong>creating a listing without sharing it is like throwing a party without inviting any guests.</strong> Nobody knows it''s happening!</p>\n  \n  <p style=\"font-size: 16px; margin-bottom: 20px;\">Here''s the step that turns your harvest into a sale: <strong>share it</strong>. CasaGrown gives every listing a link built to look good when you paste it. Put it where your neighbors already are:</p>\n\n  <!-- Sharing Channels List -->\n  <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom: 25px; background-color: #f9f9f9; border-radius: 8px; border-left: 4px solid #2e7d32;\">\n    <tr>\n      <td style=\"padding: 15px 20px;\">\n        <p style=\"margin: 0 0 12px 0; font-size: 15px;\">\n          <strong style=\"color: #2e7d32; font-size: 16px;\">1. WhatsApp</strong> \u2014 your building, street, or HOA group. The highest-converting place by far.\n        </p>\n        <p style=\"margin: 0 0 12px 0; font-size: 15px;\">\n          <strong style=\"color: #2e7d32; font-size: 16px;\">2. Nextdoor</strong> \u2014 reaches verified neighbors within blocks of you.\n        </p>\n        <p style=\"margin: 0; font-size: 15px;\">\n          <strong style=\"color: #2e7d32; font-size: 16px;\">3. Facebook</strong> \u2014 your neighborhood or local \u201cbuy nothing\u201d group.\n        </p>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Why It Works Section -->\n  <h3 style=\"font-size: 18px; color: #2e7d32; margin-top: 25px; margin-bottom: 10px; font-weight: 700;\">Why it works:</h3>\n  <p style=\"font-size: 16px; margin-bottom: 25px;\">People buy food from someone they can place. <em>\u201cThe lemon tree on Oak Street\u201d</em> beats any grocery shelf. When a neighbor sees it''s a few doors away and picked this week, it''s an easy yes.</p>\n\n  <!-- Quote Box -->\n  <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom: 25px; background-color: #f1f8e9; border-radius: 8px;\">\n    <tr>\n      <td style=\"padding: 20px; font-style: italic; font-size: 16px; color: #33691e; line-height: 1.5; text-align: center;\">\n        \"Elena made $64 her first week from lemons that used to hit the ground. The difference was sharing the listing \u2014 not just posting it.\"\n      </td>\n    </tr>\n  </table>\n\n  <p style=\"font-size: 16px; margin-bottom: 25px;\">Haven''t shared yet? Open your listing, tap <strong>Share</strong>, pick one group. That''s today''s whole task.</p>\n\n  <!-- Signoff -->\n  <p style=\"font-size: 16px; margin-bottom: 30px; line-height: 1.4;\">\n    Go share it,<br />\n    <strong>Rahul</strong><br />\n    Founder, CasaGrown\n  </p>\n\n  <!-- The One Move Section -->\n  <hr style=\"border: 0; border-top: 1px solid #eeeeee; margin: 30px 0;\" />\n  \n  <div style=\"text-align: center; margin-bottom: 30px;\">\n    <h2 style=\"font-size: 22px; color: #2e7d32; margin-bottom: 5px; font-weight: 700;\">The One Move That Works</h2>\n    <p style=\"font-size: 16px; color: #666666; margin-top: 0; margin-bottom: 15px;\">List it and share it</p>\n    <p style=\"font-size: 15px; color: #444444; margin-bottom: 20px;\">No listing yet? Create one now \u2014 the last step is sharing it.</p>\n    \n    <!-- CTA Button -->\n    <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" style=\"margin-bottom: 35px;\">\n      <tr>\n        <td align=\"center\" bgcolor=\"#2e7d32\" style=\"border-radius: 4px;\">\n          <a href=\"https://casagrown.com/r/3v25u7dz\" target=\"_blank\" style=\"font-size: 16px; font-family: sans-serif; color: #ffffff; text-decoration: none; border-radius: 4px; padding: 12px 30px; border: 1px solid #2e7d32; display: inline-block; font-weight: bold;\">List & Share \u2192</a>\n        </td>\n      </tr>\n    </table>\n  </div>\n\n  <!-- Linked Footer Image with Video Link -->\n  <div style=\"text-align: center; margin-top: 20px;\">\n    <a href=\"https://casagrown.com/r/3v25u7dz\" target=\"_blank\" style=\"text-decoration: none; display: inline-block; color: #2e7d32;\">\n      <img src=\"https://fzdmszvfeewpwswlnfyk.supabase.co/storage/v1/object/public/marketing-assets/crm/1781835018126-sharing_is_key_frame_1.jpeg\" alt=\"Sharing is Key\" style=\"max-width: 320px; width: 100%; height: auto; border-radius: 8px; border: none; display: inline-block;\" />\n    </a>\n    <p style=\"font-size: 14px; color: #666666; font-style: italic; margin-top: 15px; margin-bottom: 10px; line-height: 1.5;\">\n      Remember: creating a listing without sharing it is just like throwing a party without inviting your guests. Get the word out!\n    </p>\n  </div>\n\n</div>", "text": "CasaGrown\nfresh * local * trusted\n\nHey there,\n\nIf you''ve listed something \u2014 nice work. But remember: creating a listing without sharing it is like throwing a party without inviting any guests. Nobody knows it''s happening!\n\nHere''s the step that turns your harvest into a sale: share it. CasaGrown gives every listing a link built to look good when you paste it. Put it where your neighbors already are:\n\n1. WhatsApp \u2014 your building, street, or HOA group. The highest-converting place by far.\n\n2. Nextdoor \u2014 reaches verified neighbors within blocks of you.\n\n3. Facebook \u2014 your neighborhood or local \u201cbuy nothing\u201d group.\n\nWhy it works:\n\nPeople buy food from someone they can place. \u201cThe lemon tree on Oak Street\u201d beats any grocery shelf. When a neighbor sees it''s a few doors away and picked this week, it''s an easy yes.\n\n\"Elena made $64 her first week from lemons that used to hit the ground. The difference was sharing the listing \u2014 not just posting it.\"\n\nHaven''t shared yet? Open your listing, tap Share, pick one group. That''s today''s whole task.\n\nGo share it,\nRahul\nFounder, CasaGrown\n\n----------------------------------------------------------------------\n\nThe One Move That Works\nList it and share it\n\nNo listing yet? Create one now \u2014 the last step is sharing it.\n\nList & Share \u2192 (https://casagrown.com/r/7339wp2m)\n\nRemember: creating a listing without sharing it is just like throwing a party without inviting your guests. Get the word out!", "subject": "Your listing''s live. Now make your neighborhood see it.", "type": "action_email"}}, {"id": "n22", "type": "custom", "position": {"x": 400, "y": 2646.0}, "data": {"delayDays": 0, "delayHours": 115, "delayMinutes": 0, "type": "wait"}}, {"id": "n23", "type": "custom", "position": {"x": 400, "y": 2772.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n24", "type": "custom", "position": {"x": 400, "y": 2898.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n25", "type": "custom", "position": {"x": 50, "y": 3024.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n26", "type": "custom", "position": {"x": 400, "y": 3024.0}, "data": {"label": "read any of last 4 emails?", "conditionMode": "ai", "aiSql": "WITH ranked_sends AS (\n  SELECT \n    s.recipient_id,\n    s.recipient_type,\n    s.opened_at,\n    ROW_NUMBER() OVER (PARTITION BY s.recipient_id, s.recipient_type ORDER BY s.sent_at DESC) as rn\n  FROM crm_campaign_sends s\n  JOIN crm_campaigns c ON s.campaign_id = c.id\n  WHERE c.channel = ''email''\n),\nmatching_recipients AS (\n  SELECT DISTINCT recipient_id, recipient_type\n  FROM ranked_sends\n  WHERE rn <= 3 AND opened_at IS NOT NULL\n)\nSELECT \n  p.id,\n  ''user'' AS recipient_type,\n  p.email,\n  p.phone_number AS phone,\n  p.full_name AS name,\n  p.state_code,\n  p.city,\n  p.zip_code,\n  p.home_community_h3_index AS community_h3,\n  p.created_at AS joined_at,\n  (p.email IS NOT NULL) AS accepts_email,\n  COALESCE(p.sms_enabled, false) AS accepts_sms\nFROM profiles p\nJOIN matching_recipients mr ON p.id = mr.recipient_id AND mr.recipient_type = ''user''\n\nUNION ALL\n\nSELECT \n  l.id,\n  ''lead'' AS recipient_type,\n  l.email,\n  l.phone,\n  l.name,\n  l.state_code,\n  l.city,\n  l.zipcode AS zip_code,\n  NULL AS community_h3,\n  l.created_at AS joined_at,\n  l.accepts_email,\n  l.accepts_sms\nFROM crm_leads l\nJOIN matching_recipients mr ON l.id = mr.recipient_id AND mr.recipient_type = ''lead''", "type": "condition"}}, {"id": "n27", "type": "custom", "position": {"x": 100, "y": 3204.0}, "data": {"label": "has phone", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_phone", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n28", "type": "custom", "position": {"x": 100, "y": 3384.0}, "data": {"label": "wake-up SMS", "userLabel": "wake-up SMS", "text": "CasaGrown: Last chance! We\u2019d love to help you sell your excess produce. List your harvest today before this offer expires: https://casagrown.com/r/6255uy9s", "html": "", "subject": "", "type": "action_sms"}}, {"id": "n29", "type": "custom", "position": {"x": 400, "y": 3204.0}, "data": {"label": "Day 15", "userLabel": "Day 15", "html": "<div style=\"background-color: #f9f9f9; padding: 20px 10px; font-family: ''Helvetica Neue'', Helvetica, Arial, sans-serif; color: #2d3748; line-height: 1.6;\">\n  <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"max-width: 600px; background-color: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.05); border: 1px solid #e2e8f0;\">\n    \n    <!-- Header Section -->\n    <tr>\n      <td style=\"padding: 30px 30px 20px 30px; border-bottom: 1px solid #edf2f7; text-align: center;\">\n        <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n          <tr>\n            <td style=\"vertical-align: middle; padding-right: 12px;\">\n              <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" width=\"48\" style=\"display: block; width: 48px; height: auto; border: 0;\" />\n            </td>\n            <td style=\"vertical-align: middle; text-align: left;\">\n              <span style=\"font-size: 24px; font-weight: 800; color: #1a5f20; letter-spacing: -0.5px; display: block; line-height: 1.2;\">CasaGrown</span>\n              <span style=\"font-size: 11px; font-weight: 600; color: #718096; text-transform: uppercase; letter-spacing: 1.5px; display: block; margin-top: 2px;\">fresh &bull; local &bull; trusted</span>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n\n    <!-- Body Content Section -->\n    <tr>\n      <td style=\"padding: 40px 30px 30px 30px;\">\n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 20px; color: #4a5568;\">Hey there,</p>\n        \n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 20px; color: #4a5568; font-weight: bold;\">Two weeks since you joined. Here''s the honest math:</p>\n        \n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 20px; color: #2d3748; background-color: #fffaf0; border-left: 4px solid #dd6b20; padding: 12px 16px; border-radius: 0 4px 4px 0;\">\n          If it''s still growing and not listed, it isn''t staying neutral \u2014 <strong>it''s rotting on the branch</strong> while neighbors buy worse versions at the store.\n        </p>\n\n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 20px; color: #4a5568;\">\n          A tree doesn''t wait. The cost of doing nothing is real produce on the ground and real money left on the table. Listing is free, the wizard takes two minutes, sharing takes one tap \u2014 and it stays live all week, so there''s no perfect moment to wait for.\n        </p>\n\n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 24px; color: #4a5568;\">\n          Already listed? Then this is your nudge to add the next thing that''s ripe and re-share what''s live.\n        </p>\n\n        <!-- CTA Button Section -->\n        <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top: 10px; margin-bottom: 30px;\">\n          <tr>\n            <td align=\"center\" style=\"background-color: #2f855a; border-radius: 6px;\">\n              <a href=\"https://casagrown.com\" target=\"_blank\" style=\"display: inline-block; padding: 16px 36px; font-size: 16px; font-weight: bold; color: #ffffff; text-decoration: none; border-radius: 6px; letter-spacing: 0.5px;\">List Your Produce Now &rarr;</a>\n            </td>\n          </tr>\n        </table>\n\n        <!-- Quote Block -->\n        <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"margin-bottom: 30px; background-color: #f7fafc; border-radius: 8px;\">\n          <tr>\n            <td style=\"padding: 20px; text-align: center; font-style: italic; font-size: 17px; color: #2d3748; line-height: 1.5; font-weight: 500;\">\n              \"The fruit is going to fall whether you sell it or not. Two minutes is the difference between $0 and $40.\"\n            </td>\n          </tr>\n        </table>\n\n        <p style=\"font-size: 16px; margin-top: 0; margin-bottom: 24px; color: #4a5568;\">\n          List one thing. Share it once. That''s the entire ask this week.\n        </p>\n\n        <!-- Sign-off -->\n        <p style=\"font-size: 16px; margin-top: 30px; margin-bottom: 20px; color: #2d3748;\">\n          Don''t let it fall,<br />\n          <strong style=\"color: #1a5f20; font-size: 18px; display: block; margin-top: 5px;\">Rahul</strong>\n          <span style=\"font-size: 14px; color: #718096;\">Founder, CasaGrown</span>\n        </p>\n\n        <!-- Support Section -->\n        <p style=\"font-size: 14px; margin-top: 30px; margin-bottom: 0; color: #718096; border-top: 1px solid #edf2f7; padding-top: 20px;\">\n          Have questions or need a hand getting set up? Reach out to us anytime at <a href=\"mailto:support@casagrown.com\" style=\"color: #2f855a; text-decoration: underline; font-weight: 600;\">support@casagrown.com</a>. We''re here to help!\n        </p>\n      </td>\n    </tr>\n\n    <!-- Footer Visual Element -->\n    <tr>\n      <td style=\"background-color: #1a5f20; height: 8px; font-size: 0; line-height: 0;\">&nbsp;</td>\n    </tr>\n  </table>\n</div>", "text": "CasaGrown\nfresh \u2022 local \u2022 trusted\n\nHey there,\n\nTwo weeks since you joined. Here''s the honest math:\n\nIf it''s still growing and not listed, it isn''t staying neutral \u2014 it''s rotting on the branch while neighbors buy worse versions at the store.\n\nA tree doesn''t wait. The cost of doing nothing is real produce on the ground and real money left on the table. Listing is free, the wizard takes two minutes, sharing takes one tap \u2014 and it stays live all week, so there''s no perfect moment to wait for.\n\nAlready listed? Then this is your nudge to add the next thing that''s ripe and re-share what''s live.\n\nList Your Produce Now -> (https://casagrown.com)\n\n\"The fruit is going to fall whether you sell it or not. Two minutes is the difference between $0 and $40.\"\n\nList one thing. Share it once. That''s the entire ask this week.\n\nDon''t let it fall,\n\nRahul\nFounder, CasaGrown\n\nHave questions or need a hand getting set up? Reach out to us anytime at support@casagrown.com. We''re here to help!", "subject": "Every week it sits unlisted is produce nobody got to eat.", "type": "action_email"}}, {"id": "n30", "type": "custom", "position": {"x": 400, "y": 3384.0}, "data": {"delayDays": 0, "delayHours": 132, "delayMinutes": 0, "type": "wait"}}, {"id": "n31", "type": "custom", "position": {"x": 400, "y": 3510.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n32", "type": "custom", "position": {"x": 400, "y": 3636.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n33", "type": "custom", "position": {"x": 50, "y": 3762.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n34", "type": "custom", "position": {"x": 400, "y": 3762.0}, "data": {"label": "Day 21", "userLabel": "Day 21", "html": "<div style=\"font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333333; background-color: #ffffff; line-height: 1.6;\">\n  \n  <!-- Header / Logo Area -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom: 30px; border-bottom: 1px solid #eeeeee; padding-bottom: 20px;\">\n    <tr>\n      <td align=\"center\">\n        <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" width=\"60\" style=\"display: block; margin-bottom: 8px; max-width: 100%;\" />\n        <span style=\"font-size: 24px; font-weight: bold; color: #1e4620; letter-spacing: -0.5px; display: block;\">CasaGrown</span>\n        <span style=\"font-size: 12px; font-weight: 500; color: #767676; text-transform: uppercase; letter-spacing: 2px; display: block; margin-top: 4px;\">fresh &bull; local &bull; trusted</span>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Main Content -->\n  <p style=\"font-size: 16px; margin-bottom: 16px;\">Hey there,</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 16px;\"><strong>Isabel</strong> has two Meyer lemon trees in Menlo Park that produce far more than her family could use. For years she watched most of it rot on the branch.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 16px;\">She listed a few bags on CasaGrown\u2014which took less than two minutes\u2014and shared the link directly to her street''s WhatsApp group. Ashley lived just 0.4 miles away: two kids, cooks from scratch, and was tired of paying $8\u2013$11 for organic lemons at the store. She saw Isabel''s post in the group, messaged her immediately, and bought two bags. Her daughter even asked to go thank the grower, and they knocked on the door that very afternoon.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 16px;\">Isabel made <strong>$64 that week</strong> from fruit that was headed for the ground. They''d lived minutes apart for four years and had never met.</p>\n\n  <!-- Blockquote / Social Proof -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #f4f9f4; border-left: 4px solid #4caf50; margin: 24px 0; padding: 16px;\">\n    <tr>\n      <td>\n        <p style=\"font-size: 16px; font-style: italic; color: #2e5a2e; margin: 0; line-height: 1.5;\">\n          \"I went back to the tree after she messaged. $64 from lemons I used to throw away \u2014 because I shared the listing, not just posted it.\"\n        </p>\n        <p style=\"font-size: 14px; font-weight: bold; color: #1e4620; margin: 8px 0 0 0;\">\n          \u2014 Isabel\n        </p>\n      </td>\n    </tr>\n  </table>\n\n  <p style=\"font-size: 16px; margin-bottom: 16px;\">There''s an Ashley near you. Your listing\u2014when shared\u2014is how she finds you. But you have to take that first step quickly before the season slips away!</p>\n\n  <!-- Call to Action Button -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin: 32px 0;\">\n    <tr>\n      <td align=\"center\">\n        <a href=\"https://casagrown.com\" style=\"background-color: #2e7d32; color: #ffffff; display: inline-block; padding: 16px 32px; font-size: 18px; font-weight: bold; text-decoration: none; border-radius: 8px; box-shadow: 0 4px 6px rgba(46, 125, 50, 0.2); text-align: center;\">Create Your Listing Now</a>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Sign-off -->\n  <p style=\"font-size: 16px; margin-bottom: 0;\">Start the same way,</p>\n  <p style=\"font-size: 16px; font-weight: bold; margin-top: 4px; margin-bottom: 40px;\">\n    Rahul<br />\n    <span style=\"font-size: 14px; font-weight: normal; color: #666666;\">Founder, CasaGrown</span>\n  </p>\n\n  <!-- Help / Support Footer -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"border-top: 1px solid #eeeeee; padding-top: 20px; text-align: center;\">\n    <tr>\n      <td>\n        <p style=\"font-size: 14px; color: #666666; margin: 0; line-height: 1.5;\">\n          Have questions, need help getting set up, or want us to create your listing for you? We are here to help! Reach out to us anytime at \n          <a href=\"mailto:support@casagrown.com\" style=\"color: #2e7d32; text-decoration: underline; font-weight: 500;\">support@casagrown.com</a> and our team will get you up and running in no time.\n        </p>\n      </td>\n    </tr>\n  </table>\n\n</div>", "text": "CasaGrown\nfresh \u2022 local \u2022 trusted\n\nHey there,\n\nIsabel has two Meyer lemon trees in Menlo Park that produce far more than her family could use. For years she watched most of it rot on the branch.\n\nShe listed a few bags on CasaGrown\u2014which took less than two minutes\u2014and shared the link directly to her street''s WhatsApp group. Ashley lived just 0.4 miles away: two kids, cooks from scratch, and was tired of paying $8\u2013$11 for organic lemons at the store. She saw Isabel''s post in the group, messaged her immediately, and bought two bags. Her daughter even asked to go thank the grower, and they knocked on the door that very afternoon.\n\nIsabel made $64 that week from fruit that was headed for the ground. They''d lived minutes apart for four years and had never met.\n\n\"I went back to the tree after she messaged. $64 from lemons I used to throw away \u2014 because I shared the listing, not just posted it.\"\n\u2014 Isabel\n\nThere''s an Ashley near you. Your listing\u2014when shared\u2014is how she finds you. But you have to take that first step quickly before the season slips away!\n\nCreate Your Listing Now: https://casagrown.com/r/553m0e37\n\nStart the same way,\n\nRahul\nFounder, CasaGrown", "subject": "Isabel''s lemons were rotting. A neighbor 0.4 miles away needed them.", "type": "action_email"}}, {"id": "n35", "type": "custom", "position": {"x": 400, "y": 3942.0}, "data": {"delayDays": 0, "delayHours": 156, "delayMinutes": 0, "type": "wait"}}, {"id": "n36", "type": "custom", "position": {"x": 400, "y": 4068.0}, "data": {"label": "send window", "slots": [{"day": "mon", "end": "11:30", "start": "10:00"}, {"day": "mon", "end": "20:30", "start": "19:30"}, {"day": "tue", "end": "13:00", "start": "12:00"}, {"day": "tue", "end": "20:30", "start": "19:30"}, {"day": "wed", "end": "13:00", "start": "12:00"}, {"day": "wed", "end": "20:30", "start": "19:30"}, {"day": "thu", "end": "13:00", "start": "12:00"}, {"day": "thu", "end": "20:30", "start": "19:30"}, {"day": "fri", "end": "11:30", "start": "10:00"}, {"day": "fri", "end": "13:30", "start": "12:00"}, {"day": "sat", "end": "11:00", "start": "09:00"}, {"day": "sun", "end": "19:00", "start": "17:00"}], "type": "wait_for_slot"}}, {"id": "n37", "type": "custom", "position": {"x": 400, "y": 4194.0}, "data": {"label": "has a listing", "conditionMode": "rules", "query": {"combinator": "and", "rules": [{"field": "has_created_listings", "operator": "=", "value": "true"}]}, "type": "condition"}}, {"id": "n38", "type": "custom", "position": {"x": 50, "y": 4320.0}, "data": {"label": "has listing \u2705", "type": "terminal"}}, {"id": "n39", "type": "custom", "position": {"x": 400, "y": 4320.0}, "data": {"label": "Day 28", "userLabel": "Day 28", "html": "<div style=\"font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333333; background-color: #ffffff; line-height: 1.6;\">\n  \n  <!-- Header / Logo Section -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom: 30px; border-bottom: 1px solid #eeeeee; padding-bottom: 15px;\">\n    <tr>\n      <td valign=\"middle\" style=\"width: 50px;\">\n        <img src=\"https://casagrown.com/logo.png\" alt=\"CasaGrown Logo\" style=\"width: 40px; height: 40px; display: block; border-radius: 8px; object-fit: cover;\" />\n      </td>\n      <td valign=\"middle\" style=\"padding-left: 10px;\">\n        <div style=\"font-size: 20px; font-weight: bold; color: #1b4332; line-height: 1.2;\">CasaGrown</div>\n        <div style=\"font-size: 12px; color: #666666; line-height: 1.2; letter-spacing: 1px; text-transform: uppercase;\">fresh &bull; local &bull; trusted</div>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Email Body Content -->\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">Hey there,</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px; font-weight: bold; color: #d90429;\">This is the last message in this sequence \u2014 after today I''ll go quiet unless you come back on your own.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">One honest question first: <strong>what''s stopping you?</strong> Not a challenge \u2014 a real question. You signed up, which means something resonated. Listing is free and takes two minutes, sharing takes one tap, and your listing stays live all week.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">If it''s time \u2014 your produce will be ripe whether you list it or not. The only question is who gets to eat it.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 15px;\">If it''s uncertainty \u2014 reply to this email and tell me what''s in the way. I read every single reply.</p>\n\n  <p style=\"font-size: 16px; margin-bottom: 25px;\">And if you already listed and shared \u2014 then this isn''t for you, and well done. Add your next crop.</p>\n\n  <!-- Quote Box -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #f4f9f4; border-left: 4px solid #2d6a4f; margin-bottom: 25px;\">\n    <tr>\n      <td style=\"padding: 15px 20px;\">\n        <p style=\"font-style: italic; font-size: 15px; color: #2d6a4f; margin: 0; line-height: 1.5;\">\n          \"Most people don''t fail to act because they don''t want to. They fail because they haven''t made the decision yet. The decision is the hard part \u2014 everything after it is easy.\"\n        </p>\n      </td>\n    </tr>\n  </table>\n\n  <p style=\"font-size: 16px; margin-bottom: 25px;\">CasaGrown is here whenever you''re ready. Listing is always just two minutes away.</p>\n\n  <!-- Call to Action Section -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #1b4332; border-radius: 8px; margin-bottom: 30px; text-align: center;\">\n    <tr>\n      <td style=\"padding: 30px 20px;\">\n        <h3 style=\"color: #ffffff; margin: 0 0 10px 0; font-size: 20px; font-weight: bold;\">Whenever You''re Ready</h3>\n        <p style=\"color: #d8f3dc; margin: 0 0 20px 0; font-size: 14px;\">Two minutes to list. One tap to share. The invitation is permanent.</p>\n        <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n          <tr>\n            <td align=\"center\" style=\"background-color: #52b788; border-radius: 5px;\">\n              <a href=\"https://casagrown.com\" style=\"display: inline-block; padding: 12px 30px; color: #ffffff; text-decoration: none; font-weight: bold; font-size: 16px;\">Create a Listing &rarr;</a>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Sign-off -->\n  <p style=\"font-size: 16px; margin-bottom: 5px;\">Thanks for reading,</p>\n  <p style=\"font-size: 16px; font-weight: bold; margin-bottom: 25px; color: #1b4332;\">Rahul<br><span style=\"font-size: 14px; font-weight: normal; color: #666666;\">Founder, CasaGrown</span></p>\n\n  <p style=\"font-size: 14px; color: #666666; border-top: 1px solid #eeeeee; padding-top: 15px;\">\n    <strong>P.S.</strong> Your produce will be ripe whether you list it or not \u2014 the only question is who gets to eat it. If you need any help getting set up, just shoot us an email at <a href=\"mailto:support@casagrown.com\" style=\"color: #2d6a4f; text-decoration: underline;\">support@casagrown.com</a>.\n  </p>\n\n</div>", "text": "CasaGrown\nfresh \u2022 local \u2022 trusted\n\nHey there,\n\nThis is the last message in this sequence \u2014 after today I''ll go quiet unless you come back on your own.\n\nOne honest question first: what''s stopping you? Not a challenge \u2014 a real question. You signed up, which means something resonated. Listing is free and takes two minutes, sharing takes one tap, and your listing stays live all week.\n\nIf it''s time \u2014 your produce will be ripe whether you list it or not. The only question is who gets to eat it.\n\nIf it''s uncertainty \u2014 reply to this email and tell me what''s in the way. I read every single reply.\n\nAnd if you already listed and shared \u2014 then this isn''t for you, and well done. Add your next crop.\n\n\"Most people don''t fail to act because they don''t want to. They fail because they haven''t made the decision yet. The decision is the hard part \u2014 everything after it is easy.\"\n\nCasaGrown is here whenever you''re ready. Listing is always just two minutes away.\n\n\n*** WHENEVER YOU''RE READY ***\n\nTwo minutes to list. One tap to share. The invitation is permanent.\n\nCreate a Listing: https://casagrown.com/r/553m0e37\n\n\nThanks for reading,\n\nRahul\nFounder, CasaGrown\n\nP.S. Your produce will be ripe whether you list it or not \u2014 the only question is who gets to eat it. If you need any help getting set up, just shoot us an email at support@casagrown.com.", "subject": "This is the last one. Just one honest question first.", "type": "action_email"}}, {"id": "n40", "type": "custom", "position": {"x": 400, "y": 4500.0}, "data": {"l